                      disabled={busyId === rider.id}
                      className="flex-1 bg-green-700 text-white font-bold py-2.5 rounded-xl text-sm active:bg-green-800 disabled:opacity-50"
                    >
                      {busyId === rider.id ? 'Working…' : 'Approve'}
